entries[52200] = { ["name"] = "Zügel des scharlachroten Todesstreitrosses", ["text"] = "Wird bei Benutzung gebunden\nReittier\nBenötigt Stufe 20\nBenötigt Unerfahrener Reiter\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euer scharlachrotes Todesstreitross oder gibt es wieder frei." }
entries[52201] = { ["name"] = "Muradins Gunst", ["text"] = "Wird bei Benutzung gebunden\nEinzigartig\nSpielzeug\nBenötigt Stufe 80\nBenutzen: Ihr nehmt 10 Min. lang die Gestalt eines Frostzwergs an. (30 Min Abklingzeit)\n\"Ich werde Euch immer als meinen Bruder betrachten.\"" }
