entries[52251] = { ["name"] = "Jainas Medaillon", ["text"] = "Wird bei Benutzung gebunden\nEinzigartig\nBenötigt Stufe 80\nBenutzen: Erschafft ein Portal, das Gruppenmitglieder, die es nutzen, nach Dalaran teleportiert. (1 Stunde Abklingzeit)\n\"Einstmals enthielt das Schmuckstück ihr Bild. Er trug es immer nah an seinem Herzen.\"" }
entries[52252] = { ["name"] = "Wappenrock des Lichtbringers", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig\nWappenrock\nBenötigt Stufe 80\nBenutzen: Durchflutet seinen Träger mit Licht. (30 Min Abklingzeit)\n\"Möget Ihr stets das Licht an dunkle Orte tragen.\"" }
