entries[52277] = { ["name"] = "Geheiminformationen aus Taurajo", ["text"] = "Questgegenstand\nEinzigartig (3)\n\"Ein Stapel hingeschmierter Sendschreiben, in denen die Truppenbewegungen der Horde durch Mulgore, Durotar und das Brachland notiert sind.\"" }
