entries[52286] = { ["name"] = "Zähmerrute", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Beginnt mit der Zähmung eines Vampirnachtsaugers, damit er 15 Min. lang Euer Gefährte wird. Falls Ihr die Aufmerksamkeit des Wildtiers aus irgendeinem Grund verlieren solltet, schlägt der Vorgang der Zähmung fehl.\n3 Aufladungen" }
